import copy
import os
import time
import pandas as pd
import torch
import torch.nn as nn
import torch.optim as optim

from features import add_engineered_features
from models.ImprovedNeuralNetwork import ImprovedNeuralNetwork

device = torch.device("mps" if torch.backends.mps.is_available() else "cpu")
print(f"Training on: {device}")

# Load the throw dataset generated by ThrowSim, plus any real played throws
# logged by ThrowGame.cpp (same column schema - see logGameThrow there) so
# the model actually learns from gameplay, not just ThrowSim's uniform-
# random dataset.
df = pd.read_csv("build/throw_results.csv")
if os.path.exists("game_throws.csv"):
    game_df = pd.read_csv("game_throws.csv")
    print(f"Adding {len(game_df)} played throws from game_throws.csv")
    df = pd.concat([df, game_df], ignore_index=True)
inputs = torch.tensor(df[["vx0", "vy0", "mass", "height0", "windAccel"]].values, dtype=torch.float32).to(device)
targets = torch.tensor(df[["final_x", "final_y", "maxHeight", "timeToLand", "bounceCount", "apexTime", "finalVx"]].values, dtype=torch.float32).to(device)
inputs = add_engineered_features(inputs)

# Train/val/test split (70/15/15), shuffled. Val drives early stopping
# (so "best val loss" is somewhat cherry-picked - it's the best of many
# checkpoints on that exact set). Test is never touched until the very
# end, so it gives an honest, unbiased read on generalization.
torch.manual_seed(42)
n = inputs.shape[0]
perm = torch.randperm(n)
train_split = int(n * 0.7)
val_split = int(n * 0.85)
train_idx, val_idx, test_idx = perm[:train_split], perm[train_split:val_split], perm[val_split:]

train_inputs, train_targets = inputs[train_idx], targets[train_idx]
val_inputs, val_targets = inputs[val_idx], targets[val_idx]
test_inputs, test_targets = inputs[test_idx], targets[test_idx]

# Normalize inputs using train-set stats only (avoid leaking val/test info)
input_mean = train_inputs.mean(dim=0)
input_std = train_inputs.std(dim=0)
train_inputs = (train_inputs - input_mean) / input_std
val_inputs = (val_inputs - input_mean) / input_std
test_inputs = (test_inputs - input_mean) / input_std

# Mini-batches instead of one full-batch gradient step per epoch. At
# hundreds of thousands of rows, full-batch meant one update per epoch,
# which is a brutal waste of compute - this gives far more updates per
# pass through the data, converging faster and often to a better result.
#
# batch_size=8192 + lr=0.0025 was tried here and measured worse: 4x fewer
# gradient steps/epoch than batch_size=2048 (59 vs 239 batches), and 2.5x
# lr didn't come close to compensating - val loss was still ~35 after 800
# epochs (90 min) where the old 2048/0.001 combo reached 0.4262. Reverted
# to the proven combo. Manual on-device batching (below, instead of a
# DataLoader) is kept - that part was a real, benchmarked ~15% wall-clock
# win with no effect on convergence (same math, same batch composition,
# it just skips DataLoader's CPU-side collate machinery on tensors that
# were already moved to `device` above).
batch_size = 2048

# Instantiate the model, loss function, and optimizer
model = ImprovedNeuralNetwork().to(device)
# Huber loss instead of MSE: quadratic near zero but linear for large
# errors, so a handful of extreme throws (large vx/vy/mass combos) don't
# dominate the gradient the way squared error would. Trains outputs[:, :7]
# only - the 8th output (uncertainty) has no ground-truth column, it's
# trained separately below.
criterion = nn.HuberLoss()
optimizer = optim.Adam(model.parameters(), lr=0.001, weight_decay=1e-4)


def uncertainty_loss(outputs, targets):
    """Heteroscedastic uncertainty (Gaussian NLL): trains outputs[:, 7]
    (log_var = log of the per-axis landing-position error variance) so the
    model reports a calibrated confidence alongside its point estimate.
    The point-estimate outputs (x, y) are detached here so this loss only
    trains the uncertainty head - it doesn't also push back on x/y, which
    are already being trained by the Huber loss above.

    The NLL for two independent Gaussian axes (dx, dy), each with variance
    exp(log_var), is log_var + 0.5*exp(-log_var)*(dx^2+dy^2) - the log_var
    term appears ONCE PER AXIS, i.e. with coefficient 1, not 0.5. An
    earlier version used 0.5*log_var here (copied from the single-axis/
    scalar NLL formula), which solves to exp(log_var) = E[dx^2+dy^2] - double
    the true per-axis variance E[dx^2]. That alone made the reported
    uncertainty ~sqrt(2)x too large; combined with predict.py previously
    reporting sigma instead of the Rayleigh-distributed radial error's
    mean (sigma*sqrt(pi/2), see predict.py), predicted uncertainty came
    out several times larger than the actual mean landing error.

    log_var is clamped before exp(): at init (or early training, before
    this head has learned anything) it can land on a large-negative raw
    value, and exp(-log_var) explodes (seen in practice: a loss around
    4.6e8 in the first 20 epochs vs ~1 once trained). Because log_var
    isn't detached, that huge gradient flows back through fc10 into the
    shared trunk (fc1-fc9) - the same layers the main Huber loss is
    training - and was fighting/slowing convergence of the point-estimate
    outputs too, not just the uncertainty head. +/-10 covers sigma from
    ~0.007 to ~148, far wider than any real landing-position error here.
    """
    xy_error_sq = (outputs[:, 0].detach() - targets[:, 0]) ** 2 + (outputs[:, 1].detach() - targets[:, 1]) ** 2
    log_var = outputs[:, 7].clamp(-10.0, 10.0)
    return (0.5 * torch.exp(-log_var) * xy_error_sq + log_var).mean()

# Drops LR by 10x when val loss stalls, so late-stage training can settle
# instead of oscillating around a coarse fixed step size. Scheduler
# patience is shorter than early-stopping patience so it gets a chance
# to act before training just stops.
scheduler = optim.lr_scheduler.ReduceLROnPlateau(optimizer, mode="min", factor=0.75, patience=55)

# Train, with early stopping on val loss.
# patience=35/scheduler=15 was tried to cut wall-clock and measurably
# undertrained: stopped around val_loss~2-4 where the proven checkpoint
# needed ~0.3-0.4 to reach its accuracy - reverted to the values that
# actually produced a working model. Per-epoch is now checkpointed on
# every improvement (below), so a long patience no longer risks losing
# progress if the run needs to be cut short.
epochs = 50000
# patience raised 100 -> 175: the patience=100 run with dropout=0.1 firmly
# plateaued at val_loss~1.57 (100 epochs with zero improvement, a real
# plateau signal, not noise) - well short of the ~0.3-0.4 the dropout-off
# historical runs reached. Dropout lowered to 0.05 (models/
# ImprovedNeuralNetwork.py) to ease convergence, patience raised so a
# slower-but-still-progressing optimization isn't cut off again.
patience = 175
# Early stopping/scheduler now watch val_loss + val_unc_loss combined, not
# val_loss alone. Previously the uncertainty head could still be actively
# calibrating (its loss still trending down) when training stopped, purely
# because the point-estimate loss happened to plateau first - the
# combined metric gives calibration a real chance to finish, not just
# whatever epochs happen to fall out of the main task converging.
best_combined_loss = float("inf")
best_val_loss = float("inf")       # main-loss value at the best epoch, kept for reporting/comparability with past runs
best_val_unc_loss = float("inf")
best_state = None
epochs_no_improve = 0

n_train = train_inputs.shape[0]
n_batches = n_train // batch_size  # drop_last, same reason as the old DataLoader(drop_last=True)
train_start = time.time()

for epoch in range(epochs):
    model.train()
    # Manual on-device batching instead of a DataLoader - see the
    # batch_size comment above for why (real benchmarked ~25% speedup).
    # torch.randperm on `device` keeps the shuffle indices on-GPU too, so
    # nothing round-trips through the CPU per epoch.
    shuffle_idx = torch.randperm(n_train, device=device)
    # Accumulate on-device and only call .item() once per epoch instead of
    # once per batch - .item() forces a CPU/MPS sync, which stalls the
    # async pipeline and badly hurts throughput if done every batch.
    epoch_loss_sum = torch.zeros((), device=device)
    epoch_sample_count = 0
    for b in range(n_batches):
        batch_idx = shuffle_idx[b * batch_size:(b + 1) * batch_size]
        batch_inputs = train_inputs[batch_idx]
        batch_targets = train_targets[batch_idx]
        optimizer.zero_grad()
        outputs = model(batch_inputs)
        main_loss = criterion(outputs[:, :7], batch_targets)
        loss = main_loss + uncertainty_loss(outputs, batch_targets)
        loss.backward()
        optimizer.step()
        epoch_loss_sum += main_loss.detach() * batch_inputs.size(0)
        epoch_sample_count += batch_inputs.size(0)
    train_loss = (epoch_loss_sum / epoch_sample_count).item()

    model.eval()
    with torch.no_grad():
        val_outputs = model(val_inputs)
        val_loss = criterion(val_outputs[:, :7], val_targets)
        val_unc_loss = uncertainty_loss(val_outputs, val_targets)

    combined_val_loss = val_loss.item() + val_unc_loss.item()

    prev_lr = optimizer.param_groups[0]["lr"]
    scheduler.step(combined_val_loss)
    new_lr = optimizer.param_groups[0]["lr"]
    if new_lr != prev_lr:
        print(f"Epoch {epoch + 1}: learning rate reduced {prev_lr:.6f} -> {new_lr:.6f}")

    if (epoch + 1) % 20 == 0:
        elapsed = time.time() - train_start
        sec_per_epoch = elapsed / (epoch + 1)
        print(f"Epoch {epoch + 1}/{epochs}, Train Loss: {train_loss:.4f}, Val Loss: {val_loss.item():.4f}, "
              f"Uncertainty Loss: {val_unc_loss.item():.4f}, {sec_per_epoch:.2f}s/epoch, "
              f"{elapsed / 60:.1f}min elapsed")

    if combined_val_loss < best_combined_loss:
        best_combined_loss = combined_val_loss
        best_val_loss = val_loss.item()
        best_val_unc_loss = val_unc_loss.item()
        best_state = copy.deepcopy(model.state_dict())
        # Save on every improvement, not just at the end: if this run gets
        # killed or cut short, models/ImprovedNeuralNetwork.pth is always
        # the best checkpoint seen so far, not whatever stale/absent file
        # was there before training started.
        torch.save({
            "model_state_dict": {k: v.cpu() for k, v in best_state.items()},
            "input_mean": input_mean.cpu(),
            "input_std": input_std.cpu(),
        }, "models/ImprovedNeuralNetwork.pth")
        epochs_no_improve = 0
    else:
        epochs_no_improve += 1
        if epochs_no_improve >= patience:
            print(f"Early stopping at epoch {epoch + 1} (no val improvement for {patience} epochs)")
            break

model.load_state_dict(best_state)
print(f"Final train loss: {train_loss:.4f}")
print(f"Best val loss: {best_val_loss:.4f}")
print(f"Best val uncertainty loss: {best_val_unc_loss:.4f}")

# Honest final number: test set was never used for early stopping or any
# other decision during training, so this isn't cherry-picked like the
# val loss above can be.
model.eval()
with torch.no_grad():
    test_outputs = model(test_inputs)
    test_loss = criterion(test_outputs[:, :7], test_targets)
    test_unc_loss = uncertainty_loss(test_outputs, test_targets)
print(f"Test loss (held out, never used during training): {test_loss.item():.4f}")
print(f"Test uncertainty loss: {test_unc_loss.item():.4f}")

# Save as CPU tensors so the checkpoint loads fine on any machine,
# regardless of whether it has MPS/CUDA available.
torch.save({
    "model_state_dict": {k: v.cpu() for k, v in model.state_dict().items()},
    "input_mean": input_mean.cpu(),
    "input_std": input_std.cpu(),
}, "models/ImprovedNeuralNetwork.pth")
print("Saved weights + input normalization stats to models/ImprovedNeuralNetwork.pth")
